"""Código do notebook 01_modelagem_e_avaliacao.ipynb, copiado sem alterações.

Serve de referência para os testes de equivalência: o pacote `recommender` precisa
produzir exatamente os mesmos resultados que estas funções.

Cada bloco é o texto da célula indicada, sem alterações na lógica. As únicas
mudanças foram retirar prints/demonstrações e tornar o import do Surprise opcional.
Se o notebook mudar, atualize a célula correspondente aqui.
"""

from __future__ import annotations

import textwrap

import numpy as np
import pandas as pd

CELLS: dict[str, str] = {}

# Célula 10 — split cronológico
CELLS['split cronológico'] = 'import numpy as np\nimport pandas as pd\nfrom scipy.sparse import csr_matrix\n\n# ------------------------------------------------------------\n# Split cronológico por usuário: treino | validação | teste\n# ------------------------------------------------------------\nTEST_FRAC = 0.2   # 20% mais recentes de cada usuário -> teste\nVAL_FRAC = 0.2    # 20% mais recentes do que sobrou -> validação\n\ndef separar_ultimos(df, frac):\n    """Separa as `frac` avaliações mais recentes de cada usuário (mínimo 1)."""\n    df = df.sort_values([\'UserID\', \'Timestamp\'])\n    pos_do_fim = df.groupby(\'UserID\').cumcount(ascending=False)\n    n = df.groupby(\'UserID\')[\'MovieID\'].transform(\'size\')\n    n_corte = np.maximum(1, np.round(n * frac)).astype(int)\n    return df[pos_do_fim >= n_corte], df[pos_do_fim < n_corte]\n\ndev_df, test_df = separar_ultimos(ratings, TEST_FRAC)\ntrain_df, val_df = separar_ultimos(dev_df, VAL_FRAC)\n\n# Índices fixos de usuários e filmes (filmes na mesma ordem de `movies`)\nuser_ids = np.sort(ratings[\'UserID\'].unique())\nitem_ids = movies[\'MovieID\'].values\nu_idx = pd.Series(np.arange(len(user_ids)), index=user_ids)\ni_idx = pd.Series(np.arange(len(item_ids)), index=item_ids)\nn_users, n_items = len(user_ids), len(item_ids)\n\ndef matriz(df):\n    """Matriz esparsa usuário x filme com as notas de `df`."""\n    return csr_matrix(\n        (df[\'Rating\'].astype(np.float32).values,\n         (u_idx[df[\'UserID\']].values, i_idx[df[\'MovieID\']].values)),\n        shape=(n_users, n_items))'

# Célula 25 — TF-IDF e similaridade
CELLS['TF-IDF e similaridade'] = "from sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.metrics.pairwise import cosine_similarity\n\n# Preparar os dados de gêneros\nmovies['Genres'] = movies['Genres'].fillna('')\n\n# Vetorização dos gêneros usando TF-IDF\ntfidf = TfidfVectorizer(token_pattern=r'[^|]+')\ntfidf_matrix = tfidf.fit_transform(movies['Genres'])\n\n# Calcular a similaridade de cosseno entre filmes\ncosine_sim = cosine_similarity(tfidf_matrix, tfidf_matrix)"

# Célula 43 — avaliação
CELLS['avaliação'] = '# ------------------------------------------------------------\n# Funções de avaliação (servem tanto para a validação quanto para o teste)\n# ------------------------------------------------------------\nK = 10\nLIMIAR_RELEVANTE = 4\nDESCONTO = 1 / np.log2(np.arange(2, K + 2))   # pesos de posição do NDCG\n\ndef relevantes_de(df):\n    """Para cada usuário (índice de linha), os filmes (índices de coluna) com nota >= limiar."""\n    rel = df[df[\'Rating\'] >= LIMIAR_RELEVANTE]\n    return (rel.assign(u=u_idx[rel[\'UserID\']].values, i=i_idx[rel[\'MovieID\']].values)\n               .groupby(\'u\')[\'i\'].apply(np.array))\n\ndef vistos_de(R):\n    """Máscara densa (usuários x filmes) do que já foi avaliado na matriz R."""\n    return R.toarray() > 0\n\ndef top_k(scores, vistos, k=K):\n    """Índices dos k filmes de maior score por usuário, ignorando os já vistos."""\n    s = np.array(scores, dtype=np.float32, copy=True)\n    s[vistos] = -np.inf\n    s[np.isnan(s)] = -np.inf\n    top = np.argpartition(-s, k, axis=1)[:, :k]\n    linhas = np.arange(s.shape[0])[:, None]\n    return top[linhas, np.argsort(-s[linhas, top], axis=1)]\n\ndef avaliar(scores, nome, vistos, relevantes):\n    """Precision@K, Recall@K, NDCG@K e cobertura de catálogo."""\n    top = top_k(scores, vistos)\n    precs, recs, ndcgs = [], [], []\n    for u, rel in relevantes.items():\n        acertos = np.isin(top[u], rel)\n        precs.append(acertos.sum() / K)\n        recs.append(acertos.sum() / len(rel))\n        ndcgs.append((acertos * DESCONTO).sum() / DESCONTO[:min(len(rel), K)].sum())\n    return {\'Modelo\': nome,\n            f\'Precision@{K}\': np.mean(precs),\n            f\'Recall@{K}\': np.mean(recs),\n            f\'NDCG@{K}\': np.mean(ndcgs),\n            \'Cobertura\': len(np.unique(top[relevantes.index.values])) / n_items}'

# Célula 45 — modelos
CELLS['modelos'] = '# ------------------------------------------------------------\n# Modelos como funções: recebem os dados de ajuste e devolvem uma\n# matriz de scores (usuários x filmes). As MESMAS funções são usadas\n# na validação, no teste e no recomendador final.\n# ------------------------------------------------------------\nfrom sklearn.decomposition import TruncatedSVD\ntry:\n    from surprise import Dataset, Reader, SVD\nexcept ImportError:  # Surprise é opcional\n    pass\n\ndef score_aleatorio(R, seed=42):\n    return np.random.default_rng(seed).random(R.shape, dtype=np.float32)\n\ndef score_popularidade(R):\n    """Quantos usuários avaliaram cada filme (igual para todos os usuários)."""\n    pop = np.asarray((R > 0).sum(axis=0)).ravel().astype(np.float32)\n    return np.tile(pop, (R.shape[0], 1))\n\ndef score_svd_sklearn(R, n_components):\n    """TruncatedSVD sobre a matriz de notas (0 = não avaliado), como no notebook."""\n    modelo = TruncatedSVD(n_components=n_components, random_state=42)\n    fatores = modelo.fit_transform(R)\n    return (fatores @ modelo.components_).astype(np.float32)\n\ndef score_surprise(df, params):\n    """Nota prevista pelo SVD do Surprise para todos os pares usuário x filme."""\n    ts = Dataset.load_from_df(df[[\'UserID\', \'MovieID\', \'Rating\']],\n                              Reader(rating_scale=(1, 5))).build_full_trainset()\n    m = SVD(**params, random_state=42)\n    m.fit(ts)\n    # Montamos a matriz direto dos fatores: média + viés usuário + viés filme + p_u · q_i\n    P = np.zeros((n_users, params[\'n_factors\']), np.float32); bu = np.zeros(n_users, np.float32)\n    Q = np.zeros((n_items, params[\'n_factors\']), np.float32); bi = np.zeros(n_items, np.float32)\n    for raw_uid in df[\'UserID\'].unique():\n        inner = ts.to_inner_uid(raw_uid)\n        P[u_idx[raw_uid]], bu[u_idx[raw_uid]] = m.pu[inner], m.bu[inner]\n    for inner in ts.all_items():\n        j = i_idx[ts.to_raw_iid(inner)]\n        Q[j], bi[j] = m.qi[inner], m.bi[inner]\n    return ts.global_mean + bu[:, None] + bi[None, :] + P @ Q.T\n\ndef score_conteudo(R, ponderado):\n    """Perfil do usuário = soma das similaridades (gêneros) com os filmes que ele viu.\n    ponderado=True: cada filme pesa (nota - média do usuário), então filmes de que\n    ele não gostou passam a afastar recomendações parecidas."""\n    if not ponderado:\n        pesos = (R > 0).astype(np.float32)\n    else:\n        coo = R.tocoo()\n        media = np.asarray(R.sum(axis=1)).ravel() / np.maximum(1, R.getnnz(axis=1))\n        pesos = csr_matrix((coo.data - media[coo.row], (coo.row, coo.col)), shape=R.shape)\n    return np.asarray(pesos @ cosine_sim, dtype=np.float32)\n\ndef minmax_por_usuario(scores, vistos):\n    """Normaliza os scores de cada usuário para [0, 1], considerando só os filmes não vistos."""\n    s = np.array(scores, dtype=np.float32, copy=True)\n    s[vistos] = np.nan\n    mn = np.nanmin(s, axis=1, keepdims=True)\n    mx = np.nanmax(s, axis=1, keepdims=True)\n    return (s - mn) / (mx - mn + 1e-9)\n\ndef alpha_adaptativo(R, c):\n    """α_u = n_u / (n_u + c): mais avaliações -> mais peso no colaborativo."""\n    n = R.getnnz(axis=1)\n    return (n / (n + c)).astype(np.float32)[:, None]\n\ndef combinar(colab, conteudo, R, vistos, alpha=None, c=None, normalizar=True):\n    """Combina os dois scores. Use `alpha` (fixo) OU `c` (α adaptativo)."""\n    if normalizar:\n        colab, conteudo = minmax_por_usuario(colab, vistos), minmax_por_usuario(conteudo, vistos)\n    a = alpha_adaptativo(R, c) if c is not None else alpha\n    return a * colab + (1 - a) * conteudo\n\ndef score_hibrido(R, config):\n    """Híbrido completo a partir de uma configuração (dict) escolhida na validação."""\n    vistos = vistos_de(R)\n    colab = score_svd_sklearn(R, config[\'n_components\'])\n    conteudo = score_conteudo(R, ponderado=config[\'conteudo_ponderado\'])\n    return combinar(colab, conteudo, R, vistos,\n                    alpha=config.get(\'alpha\'), c=config.get(\'c\'))'

# Célula 55 — recomendador final
CELLS['recomendador final'] = 'def criar_recomendador(df, config):\n    """Ajusta o híbrido em `df` e devolve uma função recomendar(user_id, n)."""\n    R = matriz(df)\n    vistos = vistos_de(R)\n    scores = score_hibrido(R, config)\n\n    def recomendar(user_id, n=10):\n        if user_id not in u_idx.index:\n            return f"UserID {user_id} não encontrado."\n        u = u_idx[user_id]\n        # mesma rotina de top-K da avaliação (já exclui os filmes vistos)\n        top = top_k(scores[u:u + 1], vistos[u:u + 1], k=n)[0]\n        rec = movies.iloc[top][[\'MovieID\', \'Title\', \'Genres\']].copy()\n        rec[\'Score\'] = scores[u, top]\n        return rec.reset_index(drop=True)\n\n    return recomendar'


def load(movies: pd.DataFrame, ratings: pd.DataFrame) -> dict:
    """Executa as células com `movies` e `ratings` e devolve o namespace resultante,
    como se o notebook tivesse sido rodado até o fim com esses dados."""
    namespace = {"movies": movies.copy(), "ratings": ratings.copy(), "np": np, "pd": pd}
    for code in CELLS.values():
        exec(textwrap.dedent(code), namespace)
    return namespace
